"""Rebuild comparative metrics from independently audited isolated research ledgers."""
import json,html,hashlib,gzip,shutil
from pathlib import Path
from datetime import datetime,timezone
from zoneinfo import ZoneInfo
import pandas as pd,numpy as np
ROOT=Path(__file__).resolve().parents[2];OUT=ROOT/'public/reports'

def main():
 r=json.loads((OUT/'consolidation-research-results.json').read_text(encoding='utf-8'))
 columns=['sym','box_id','box_tf','config','model','target','policy','entry_at','exit_at','year','outcome','r','net_5bps_r','net_10bps_r','with_bias','with_4h_bias','with_both_bias'];a=pd.read_csv(OUT/'consolidation-research-trades.csv',usecols=columns);b=pd.read_csv(OUT/'consolidation-prearmed-trades.csv',usecols=columns);df=pd.concat([a,b],ignore_index=True);df['cohort_id']=df[['box_tf','config','model','target','policy']].astype(str).agg('|'.join,axis=1)
 del a,b
 with gzip.open(OUT/'consolidation-research-all-trades.csv.gz','wb',compresslevel=6) as out:
  for i,path in enumerate((OUT/'consolidation-research-trades.csv',OUT/'consolidation-prearmed-trades.csv')):
   with path.open('rb') as src:
    if i:src.readline()
    shutil.copyfileobj(src,out)
 r['models']=sorted(df.model.unique());r['entry_models']=r['models'];r['exit_policies'].update(HARD5_EOD='hard5m SL and session-flat',CLOSE5_EOD='close5m SL and session-flat');r['metrics']=[];r['rows']=len(df);r['unique_entry_events']=len(df[['sym','box_id','model','entry_at']].drop_duplicates());r['walk_forward']=[]
 for filt in ('all','daily','4h','both'):
  sub=df if filt=='all' else df[df[{'daily':'with_bias','4h':'with_4h_bias','both':'with_both_bias'}[filt]]]
  for keys,g in sub.groupby(['box_tf','config','model','target','policy']):
   s=g[g.outcome.isin(['win','loss','time_exit'])];gross=s.r;net=s.net_5bps_r;hold=(s.exit_at-s.entry_at)/3600000
   years=[dict(year=int(y),n=len(t),avg_r=float(t.r.mean()),net_5bps_r=float(t.net_5bps_r.sum()),avg_net_5bps_r=float(t.net_5bps_r.mean())) for y,t in s.groupby('year')]
   pf=float(gross[gross>0].sum()/abs(gross[gross<0].sum())) if (gross<0).any() else None
   train=s[(s.year<2022)&(s.exit_at<int(datetime(2022,1,1,tzinfo=ZoneInfo('America/New_York')).timestamp()*1000))];test=s[s.year>=2022]
   m=dict(zip(['box_tf','config','model','target','policy'],keys),bias_filter=filt,total=len(g),closed=len(s),gross_win_pct=float((s.r>0).mean()*100) if len(s) else None,target_hit_pct=float((s.outcome=='win').mean()*100) if len(s) else None,win_pct=float((s.net_5bps_r>0).mean()*100) if len(s) else None,avg_r=float(gross.mean()) if len(s) else None,gross_r=float(gross.sum()),net_5bps_r=float(net.sum()),avg_net_5bps_r=float(net.mean()) if len(s) else None,net_10bps_r=float(s.net_10bps_r.sum()),profit_factor=pf,worst_r=float(gross.min()) if len(s) else None,median_hold_h=float(hold.median()) if len(s) else None,p90_hold_h=float(hold.quantile(.9)) if len(s) else None,unverified=int(g.outcome.isin(['unverified','invalid_execution']).sum()),invalid_execution=int((g.outcome=='invalid_execution').sum()),open=int((g.outcome=='open').sum()),train_n=len(train),train_net_r=float(train.net_5bps_r.sum()),test_n=len(test),test_net_r=float(test.net_5bps_r.sum()),test_avg_r=float(test.net_5bps_r.mean()) if len(test) else None,years=years)
   r['metrics'].append(m)
 # Choose only using complete trades before each test year; bias filters are part of candidates.
 candidates=pd.concat([df.assign(bias_filter='all'),df[df.with_bias].assign(bias_filter='daily'),df[df.with_4h_bias].assign(bias_filter='4h'),df[df.with_both_bias].assign(bias_filter='both')],ignore_index=True)
 for policy in ('HARD5','CLOSE5','HARD5_EOD','CLOSE5_EOD'):
  for tf in ('1d','1h','30m','15m'):
   for year in range(2022,2027):
    bound=int(datetime(year,1,1,tzinfo=ZoneInfo('America/New_York')).timestamp()*1000);base=candidates[(candidates.policy==policy)&(candidates.box_tf==tf)&candidates.outcome.isin(['win','loss','time_exit'])];train=base[(base.year<year)&(base.exit_at<bound)];groups=train.groupby(['config','model','target','bias_filter']).net_5bps_r.agg(['count','mean']);groups=groups[groups['count']>=100]
    if not len(groups):continue
    winner=groups['mean'].idxmax();test=base[(base.year==year)&(base.config==winner[0])&(base.model==winner[1])&(base.target==winner[2])&(base.bias_filter==winner[3])]
    r['walk_forward'].append(dict(policy=policy,box_tf=tf,year=year,selected=list(winner),train_n=int(groups.loc[winner,'count']),train_avg_net_r=float(groups.loc[winner,'mean']),test_n=len(test),test_net_r=float(test.net_5bps_r.sum()),test_avg_net_r=float(test.net_5bps_r.mean()) if len(test) else None))
 r['prearmed_parameters']={'EDGE_TOUCH':'range edge entry; stop0.25 range outside edge','RAID_10PCT':'limit0.10 range outside edge; stop0.35 range outside edge','expiry':'10 parent bars after completed confirmation','decision':'entry/stop/targets predeclared; countertrend side of first limit hit, one selected event per box'}
 audit=json.loads((OUT/'consolidation-research-validation.json').read_text(encoding='utf-8')) if (OUT/'consolidation-research-validation.json').exists() else {};r['validation']={k:v for k,v in audit.items() if k!='examples'}
 r['source_lessons']=[{'title':'Month09 Trading in Consolidations','url':'https://www.youtube.com/watch?v=g7jchu4g31c','primary_transcript':'auto-generated captions exported from original YouTube video','points':[{'time':'0:36-1:21','rule':'Daily/4H directional context; lower-timeframe consolidation'},{'time':'6:01-7:13','rule':'Fade expansion away from equilibrium in the higher-timeframe direction; opposing range side is a possible objective'},{'time':'12:08-13:23','rule':'Buy below the old low in bullish context; return to equilibrium rather than assuming the opposite boundary'},{'time':'14:19-14:40','rule':'Bearish-context sell above old highs'}]},{'title':'Month02 Market Maker Trap False Breakouts','url':'https://www.youtube.com/watch?v=pv2-R-STviA','primary_transcript':'unavailable in this session; verified original video title only'},{'title':'2022 Mentorship Episode6','url':'https://www.youtube.com/watch?v=Bkt8B3kLATQ','primary_transcript':'unavailable in this session; MSS/FVG implementation is a separately labelled local hypothesis'}]
 r['limits']=['All numerical box thresholds, displacement threshold, order expiry, stop buffer, trend proxy and cost levels are LOCAL_ADAPTATION. This is not a literal complete ICT implementation.','Fixed current31-symbol universe has survivorship risk; historic constituents were not reconstructed.','Complete raw5m source, native gaps and conflict exclusion; no price clipping or invented tails. Corporate-action price continuity remains a review boundary.','Daily/4H context is a causal2-bar-fractal order-flow proxy, not the full ICT PD-array matrix.','Market entries use next5m open after completed confirmation. Same-boundary close/open fills are OHLC assumptions; no tick/quote execution proof.','Resting limits filled at the bar open can exit in that bar. A fill-bar stop without a target is scored as a loss. Intrabar target-before/after-fill ambiguity remains unscored; missing paths and large discontinuities are also unscored.','CE/opposite objectives already reached after the raid and before confirmation/fill are missed opportunities;2R is a synthetic comparator.','Cost5bps/10bps is a round-trip sensitivity, not broker-confirmed costs. Sum R across overlapping variants is not a portfolio return.','Historical walk-forward selection uses only prior closed trades; these are already-seen historical data, not a fresh blind holdout or live-performance guarantee.','Frozen original consolidation runs and realtime routes are not replaced by these experiments.']
 for m in r['metrics']:
  m['net_1bps_r']=m['gross_r']-(m['gross_r']-m['net_5bps_r'])/5
  m['break_even_round_trip_bps']=5*m['gross_r']/(m['gross_r']-m['net_5bps_r']) if m['gross_r']>0 and m['gross_r']>m['net_5bps_r'] else 0
 r['experiment_code_sha256']={str(p.relative_to(ROOT)):hashlib.sha256(p.read_bytes()).hexdigest() for p in (ROOT/'scripts/consolidation/research_models.py',ROOT/'scripts/consolidation/research_edge_limits.py')}
 # Month-block uncertainty for a limited shortlist; not corrected for model-selection multiplicity.
 shortlist=sorted([m for m in r['metrics'] if m['closed']>=300 and m['policy']=='CLOSE5_EOD'],key=lambda m:m['avg_net_5bps_r'],reverse=True)[:12];rng=np.random.default_rng(20261013);r['shortlist_uncertainty']=[]
 for m in shortlist:
  g=df[(df.box_tf==m['box_tf'])&(df.config==m['config'])&(df.model==m['model'])&(df.target==m['target'])&(df.policy==m['policy'])&df.outcome.isin(['win','loss','time_exit'])].copy()
  if m['bias_filter']!='all':g=g[g[{'daily':'with_bias','4h':'with_4h_bias','both':'with_both_bias'}[m['bias_filter']]]]
  g=g[g.year>=2022];months=pd.to_datetime(g.entry_at,unit='ms',utc=True).dt.tz_convert('America/New_York').dt.strftime('%Y-%m');blocks=g.groupby(months).net_5bps_r.agg(['sum','count'])
  if len(blocks)<12:continue
  ix=rng.integers(0,len(blocks),size=(2000,len(blocks)));means=blocks['sum'].to_numpy()[ix].sum(axis=1)/blocks['count'].to_numpy()[ix].sum(axis=1);ci=np.quantile(means,[.025,.975])
  r['shortlist_uncertainty'].append({k:m[k] for k in ('box_tf','config','model','target','policy','bias_filter')}|dict(test_n=len(g),test_avg_net_r=float(g.net_5bps_r.mean()),month_blocks=len(blocks),ci95_low=float(ci[0]),ci95_high=float(ci[1]),scope='2022+ month-block bootstrap; selection multiplicity not adjusted'))
 r['producing_code_sha256']=r.get('code_sha256');r['independent_audit_code_sha256']=hashlib.sha256((ROOT/'scripts/consolidation/validate_research.py').read_bytes()).hexdigest()
 r['prearmed_source_audits']=json.loads((OUT/'consolidation-prearmed-results.json').read_text(encoding='utf-8'))
 (OUT/'consolidation-research-results.json').write_text(json.dumps(r,default=str,indent=2),encoding='utf-8')
 r['session_flat_policy']='EOD variants close at actual last completed5m close of official entry-day XNYS session, including early closes; no overnight exposure. Time exits count with actual positive/negative R.'
 r['tested_scope']='Range-edge fades, confirmed post-raid entries and breakout-retest comparator. Inside-range internal-swing fades and full ICT PD-matrix context are not implemented in this first measured study.'
 # Interactive static research report, no trade execution.
 page="""<!doctype html><html><meta charset="utf-8"><title>ICT Consolidation Research</title><style>body{background:#101620;color:#e2e8f0;font:15px system-ui;margin:28px;padding:0 10px}a{color:#7dd3fc}select{padding:8px;background:#1e293b;color:white;margin:5px;border:1px solid #64748b}table{border-collapse:collapse;width:100%;font-size:12px;margin-top:15px}th,td{padding:8px;border:1px solid #334155;text-align:left}th{background:#1e293b;position:sticky;top:0}.warn{padding:15px;background:#422006;border-radius:6px}li{margin:8px 0}</style><h1>ICT Consolidation: measured research experiments</h1><p id="scope"></p><p class="warn">Exploratory historical results. Choose an entry path, target and exit rule; profitable-looking cells are candidates for validation. Unscored source/sequence cases remain excluded. The original Consolidation tab is not replaced.</p><p><a href="https://www.youtube.com/watch?v=g7jchu4g31c&t=749s" target="_blank">Original ICT lesson: equilibrium objective,12:29</a> · <a href="consolidation-research-results.json">Complete research metadata</a> · <a href="consolidation-research-all-trades.csv.gz">Full trade ledger CSV (gzip)</a></p><h2>Models and assumptions</h2><p>Prearmed limits enter at the known range edge or10% beyond it, with stops25% or35% outside the edge. Confirmed fades enter after a completed5m raid/reclaim. MSS entries require a confirmed opposite swing break and a candle body≥60% of its range; the FVG version uses a formed three-candle gap's midpoint. All thresholds are local experiments. The EOD policies flatten at the official session close if neither exit triggered; early-close sessions are respected. Targets are the frozen range midpoint(CE), opposite edge or synthetic2R. Stops compare hard5m stop-first with strict5m-close SL and wick TP-first.</p><label>Box timeframe <select id="tf"><option>1h</option><option>15m</option><option>30m</option><option>1d</option></select></label><label>Compression <select id="cfg"><option>tight</option><option>standard</option></select></label><label>Context <select id="bias"><option value="all">All first events</option><option value="daily">Daily aligned proxy</option><option value="4h">4H aligned proxy</option><option value="both">Daily+4H aligned proxy</option></select></label><label>Stop <select id="stop"><option value="CLOSE5_EOD">5m close SL + flat session end</option><option value="CLOSE5">5m close SL, hold overnight</option><option value="HARD5">5m hard SL</option><option value="HARD5_EOD">5m hard SL + flat session end</option></select></label><label>Target <select id="target"><option>CE</option><option>OPPOSITE</option><option>2R</option></select></label><div id="results"></div><h2>Annual train-only selection</h2><p>For each test year, choose the best mean net R model on prior fully closed trades only, with≥100 training trades. Models/context/targets compete within each box timeframe and exit policy. Historical replay; not an untouched holdout.</p><div id="wf"></div><h2>How far this study goes</h2><p>These tests address range-edge fades, post-raid MSS/FVG entries and a breakout-retest comparator. Inside-range internal-swing fades and the complete ICT PD-array matrix remain unimplemented. A swing-break bias proxy is a measurable comparison, not a claim to reproduce ICT discretionary order flow.</p><p><a href="consolidation-research-validation.json">Independent validation and raw candle examples</a></p><h2>Evidence boundaries</h2><ul id="limits"></ul><script>let data;const ids=['tf','cfg','bias','stop','target'];const names={PREARMED_EDGE_TOUCH:'Resting fade at edge',PREARMED_RAID_10PCT:'Resting fade10% beyond edge',RAID_FADE:'Fade after5m raid',CLOSE_BREAK_FADE:'Fade after breakout close',RECLAIM_FADE:'Wait for reclaim',MSS5_MARKET:'Raid→5m MSS→next open',MSS15_MARKET:'Raid→15m MSS→next open',MSS5_FVG_CE:'Raid→5m MSS→FVG midpoint',EXPANSION_OB_RETEST:'Expansion→candle-open retest'};const fmt=(x,d=2)=>x==null?'—':Number(x).toFixed(d);const table=(heads,rows)=>'<table><tr>'+heads.map(h=>'<th>'+h+'</th>').join('')+'</tr>'+rows.map(r=>'<tr>'+r.map(c=>'<td>'+c+'</td>').join('')+'</tr>').join('')+'</table>';function draw(){if(!data)return;let [tf,cfg,bias,stop,target]=ids.map(x=>document.getElementById(x).value);let m=data.metrics.filter(m=>m.box_tf===tf&&m.config===cfg&&m.bias_filter===bias&&m.policy===stop&&m.target===target).sort((a,b)=>(b.avg_net_5bps_r??-Infinity)-(a.avg_net_5bps_r??-Infinity));document.getElementById('results').innerHTML=table(['Entry model','Closed','Net win%5bps','Gross R','Net R1bps','Net R5bps','Avg net R','Net R10bps','2022+ n','2022+ net R','Worst R','Median hold h','Unscored','Open'],m.map(m=>[names[m.model]||m.model,m.closed,fmt(m.win_pct,1),fmt(m.gross_r),fmt(m.net_1bps_r),fmt(m.net_5bps_r),fmt(m.avg_net_5bps_r,3),fmt(m.net_10bps_r),m.test_n,fmt(m.test_net_r),fmt(m.worst_r),fmt(m.median_hold_h,1),m.unverified,m.open]));let w=data.walk_forward.filter(w=>w.box_tf===tf&&w.policy===stop);document.getElementById('wf').innerHTML=table(['Year','Selected parameters','Train n','Train avg net R','Test n','Test net R','Test avg net R'],w.map(w=>[w.year,w.selected.join(' / '),w.train_n,fmt(w.train_avg_net_r,3),w.test_n,fmt(w.test_net_r),fmt(w.test_avg_net_r,3)]));}fetch('consolidation-research-results.json').then(r=>r.json()).then(r=>{data=r;document.getElementById('scope').textContent=r.universe.length+' symbols ·2017–2026 ·'+r.rows.toLocaleString()+' overlapping trade variants ·9 entry models ·4 box timeframes ·4 exit/holding policies';document.getElementById('limits').innerHTML=r.limits.map(x=>'<li>'+x+'</li>').join('');draw()});ids.forEach(x=>document.getElementById(x).addEventListener('change',draw));</script></html>"""
 (OUT/'consolidation-research-results.html').write_text(page,encoding='utf-8');print('REPORT',len(df),len(r['metrics']),len(r['walk_forward']))
if __name__=='__main__':main()
